package com.example.rokidgeminisecretary;
import android.content.*;import android.net.*;import org.json.*;
/** One expiring explicit transfer. No boot receiver, no retry after an uncertain dispatch. */
final class ScheduledTransfer {
 static long lastTick;static boolean working;
 static JSONObject environment(Context c)throws Exception{Intent b=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));boolean charging=b!=null&&b.getIntExtra("plugged",0)>0;ConnectivityManager cm=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);NetworkCapabilities n=null;try{n=cm==null?null:cm.getNetworkCapabilities(cm.getActiveNetwork());}catch(SecurityException unavailable){}boolean wifi=n!=null&&n.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)&&!n.hasTransport(NetworkCapabilities.TRANSPORT_VPN);return new JSONObject().put("charging",charging).put("wifi",wifi).put("connected",ConversationWorkspace.snapshot(c).optBoolean("connected"));}
 static synchronized JSONObject read(Context c)throws Exception{JSONObject workspace=ConversationWorkspace.snapshot(c);if(workspace.optBoolean("connected")&&workspace.optJSONArray("reservations")!=null)observe(c,workspace.getJSONArray("reservations"));JSONObject j=ReviewStore.read(c,"scheduled-transfer");if(j.optString("state").equals("waiting")){JSONObject e=environment(c);j.put("reason",MaintenancePolicy.transferReason(e.getBoolean("connected"),e.getBoolean("charging"),e.getBoolean("wifi"),j.optBoolean("charging"),j.optBoolean("wifi"),System.currentTimeMillis(),j.optLong("expiresAt")));}if(j.has("dispatchedAt")&&!j.optString("state").matches("waiting|cancelled|queue-failed|result-received")&&System.currentTimeMillis()-j.optLong("lastResultAt",j.optLong("dispatchedAt"))>1800000)j.put("state","result-unconfirmed").put("reason","30分間新しい予約結果がありません。再送前にグラスと保存結果を確認してください");return j.put("notificationsEnabled",TransferResultNotice.enabled(c)).put("notificationsAvailable",TransferResultNotice.available(c));}
 static synchronized JSONObject schedule(Context c,JSONObject in)throws Exception{String kind=in.getString("kind");if(!kind.matches("photo|meeting"))throw new IllegalArgumentException("転送種別を選んでください");JSONObject old=read(c);if(old.optString("state").matches("dispatch-unconfirmed|queued-unconfirmed|remote-active")||old.optString("state").equals("waiting")&&old.optLong("expiresAt")>System.currentTimeMillis())throw new java.io.IOException("予約済みです。中止してから変更してください");JSONObject j=new JSONObject().put("id",java.util.UUID.randomUUID().toString()).put("kind",kind).put("charging",in.getBoolean("charging")).put("wifi",in.getBoolean("wifi")).put("state","waiting").put("createdAt",System.currentTimeMillis()).put("expiresAt",System.currentTimeMillis()+6*3600000L);ReviewStore.write(c,"scheduled-transfer",j);TransferResultNotice.clear(c);return read(c);}
 static synchronized JSONObject cancel(Context c,String id)throws Exception{JSONObject j=read(c);if(!id.equals(j.optString("id"))||!j.optString("state").equals("waiting"))throw new java.io.IOException("予約状態が変わりました");j.put("state","cancelled");ReviewStore.write(c,"scheduled-transfer",j);return j;}
 static synchronized JSONObject dispatch(Context c,String id,boolean manual)throws Exception{JSONObject j=read(c);if(!id.equals(j.optString("id"))||!j.optString("state").equals("waiting"))throw new java.io.IOException("予約状態が変わりました");JSONObject e=environment(c);String reason=MaintenancePolicy.transferReason(e.getBoolean("connected"),e.getBoolean("charging"),e.getBoolean("wifi"),!manual&&j.optBoolean("charging"),!manual&&j.optBoolean("wifi"),System.currentTimeMillis(),j.optLong("expiresAt"));if(!reason.isEmpty())throw new java.io.IOException(reason);j.put("state","dispatch-unconfirmed").put("dispatchedAt",System.currentTimeMillis());ReviewStore.write(c,"scheduled-transfer",j);JSONObject cmd=new JSONObject().put("id",j.getString("id")).put("kind",j.getString("kind")).put("expiresAt",System.currentTimeMillis()+120000);boolean queued=MainActivity.queueBridgeCommand(c,"__LOKI_TRANSFER_ONCE__:"+cmd,true);j.put("state",queued?"queued-unconfirmed":"queue-failed").put("reason",queued?"グラスの実行・保存結果は転送状況で確認してください。自動再送しません":"送信待ちに追加できませんでした。自動再送しません");ReviewStore.write(c,"scheduled-transfer",j);return j;}
 static synchronized void observe(Context c,JSONArray receipts)throws Exception{if(receipts==null)return;if(receipts.length()>8)throw new java.io.IOException("予約結果が多すぎます");JSONObject j=ReviewStore.read(c,"scheduled-transfer");if(j.optString("id").isEmpty()||!j.has("dispatchedAt"))return;for(int i=0;i<receipts.length();i++){JSONObject remote=receipts.getJSONObject(i);if(!j.optString("id").equals(remote.optString("id"))||!j.optString("kind").equals(remote.optString("kind")))continue;String phase=remote.optString("phase"),old=j.optString("remotePhase");if(!phase.matches("ACCEPTED|RUNNING|COMPLETED|PARTIAL|FAILED|REJECTED|INTERRUPTED|EXPIRED"))continue;if(ExperiencePolicy.terminal(old)||old.equals("RUNNING")&&phase.equals("ACCEPTED"))continue;String batch=remote.optString("batchId");if(!batch.isEmpty()&&!batch.matches("[a-f0-9-]{36}"))continue;if(j.has("batchId")&&!batch.isEmpty()&&!batch.equals(j.optString("batchId")))continue;long expected=Math.max(0,Math.min(100000,remote.optLong("expected"))),confirmed=Math.max(0,Math.min(expected,remote.optLong("confirmed"))),retained=Math.max(0,Math.min(expected-confirmed,remote.optLong("retained")));if(phase.equals("COMPLETED")&&confirmed+retained<expected)phase="PARTIAL";JSONObject next=new JSONObject(j.toString()).put("remotePhase",phase).put("state",ExperiencePolicy.terminal(phase)?"result-received":"remote-active").put("reason",ExperiencePolicy.transferLabel(phase)+" / "+remote.optString("reason").substring(0,Math.min(180,remote.optString("reason").length()))).put("confirmed",confirmed).put("expected",expected).put("retained",retained);if(!batch.isEmpty())next.put("batchId",batch);if(!next.toString().equals(j.toString())){next.put("lastResultAt",System.currentTimeMillis());ReviewStore.write(c,"scheduled-transfer",next);if(!old.equals(phase))TransferResultNotice.show(c,next);}return;}}
 static void tick(Context c){synchronized(ScheduledTransfer.class){long now=android.os.SystemClock.elapsedRealtime();if(working||now-lastTick<30000)return;lastTick=now;working=true;}new Thread(()->{try{JSONObject j=read(c);if(j.optString("state").equals("waiting")&&j.optString("reason").isEmpty())dispatch(c,j.getString("id"),false);}catch(Exception ignored){}finally{synchronized(ScheduledTransfer.class){working=false;}}},"ScheduledTransfer").start();}
 private ScheduledTransfer(){}
}
